document.addEventListener("click",function(c){let t=c.target.closest(".faq-question");if(!t)return;let e=t.closest(".faq-item");if(!e)return;let n=e.classList.contains("is-active");document.querySelectorAll(".faq-item").forEach(function(s){s.classList.remove("is-active");let i=s.querySelector(".faq-question");i&&i.setAttribute("aria-expanded","false")}),n||(e.classList.add("is-active"),t.setAttribute("aria-expanded","true"))});
